const themes=<?php echo json_encode($themes, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE); ?>;
(()=>{const root=document.documentElement,page=document.getElementById('page'),layout=document.getElementById('layout'),rail=document.getElementById('themesRail'),copyToast=document.getElementById('copyToast'),openLink=document.getElementById('open');let active=0,timer,progressTimer,pct=0,toastTimer;
const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const twoLine=s=>{const words=String(s).split(' ');if(words.length<5)return esc(s);const mid=Math.ceil(words.length/2);return esc(words.slice(0,mid).join(' '))+'<br>'+esc(words.slice(mid).join(' '));};
function showCopied(code){if(!copyToast)return;copyToast.textContent=code+' copied';copyToast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>copyToast.classList.remove('show'),1200)}
async function copyColor(code){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(code)}else{const ta=document.createElement('textarea');ta.value=code;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}showCopied(code)}catch(e){showCopied('Copy failed: '+code)}}
if(rail) rail.innerHTML=themes.map((t,i)=>`<button class="chip ${i?'':'active'}" data-i="${i}" style="--chip-color:${t.colors[0]}"><b>${esc(t.name)}</b><span>${String(i+1).padStart(2,'0')}</span></button>`).join('');
function setVars(t){let c=t.colors;root.style.setProperty('--img',`url('${t.image}')`);root.style.setProperty('--pos',t.position||'center center');root.style.setProperty('--c1',c[0]);root.style.setProperty('--c2',c[1]);root.style.setProperty('--c3',c[2]);root.style.setProperty('--c4',c[3]);root.style.setProperty('--dark',c[1]);root.style.setProperty('--light',c[5]);}
function render(i){active=(i+themes.length)%themes.length;const t=themes[active];page.classList.add('is-changing');layout.classList.remove('ready');setTimeout(()=>{setVars(t);title.innerHTML=t.name.includes(' ')?esc(t.name).replace(/ (\S+)$/,' <em>$1</em>'):esc(t.name);tagline.textContent=t.tagline;coverPhrase.innerHTML=twoLine(t.phrase);indexMark.textContent=String(active+1).padStart(2,'0')+' / '+themes.length;kicker.textContent='Design language';count.textContent=String(active+1).padStart(2,'0')+' / '+themes.length;openLink.href=t.href;description.textContent='A refined, image-led presentation of '+t.name+' — using palette overlays, disciplined contrast and a clean editorial reveal.';swatches.innerHTML=t.colors.map(x=>`<button class="swatch" type="button" style="background:${x}" data-code="${esc(x)}" aria-label="Copy ${esc(x)}" title="Copy ${esc(x)}"></button>`).join('');miniName.textContent=t.name;document.querySelectorAll('.chip').forEach((b,n)=>b.classList.toggle('active',n===active));document.querySelector('.chip.active')?.scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'});layout.classList.add('ready');},140);setTimeout(()=>page.classList.remove('is-changing'),760);restart();}
function restart(){clearInterval(timer);clearInterval(progressTimer);pct=0;progress.style.width='0%';timer=setInterval(()=>render(active+1),6800);progressTimer=setInterval(()=>{pct=Math.min(100,pct+100/(6800/120));progress.style.width=pct+'%'},120)}
swatches.addEventListener('click',e=>{const btn=e.target.closest('.swatch');if(btn)copyColor(btn.dataset.code)});
openLink.addEventListener('click',e=>{e.preventDefault();window.location.href=themes[active].href});
next.onclick=()=>render(active+1);prev.onclick=()=>render(active-1);addEventListener('keydown',e=>{if(e.key==='ArrowRight')render(active+1);if(e.key==='ArrowLeft')render(active-1)});render(0);})();
</script>
</body>
</html>